"import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:jarvis/data/models/user_model.dart';
import 'package:jarvis/data/repositories/user_repository.dart';

final userRepositoryProvider = Provider<UserRepository>((ref) {
  return UserRepository();
});

final userProvider =
    StateNotifierProvider<UserNotifier, AsyncValue<UserModel?>>((ref) {
  return UserNotifier(ref.watch(userRepositoryProvider));
});

class UserNotifier extends StateNotifier<AsyncValue<UserModel?>> {
  final UserRepository _repository;

  UserNotifier(this._repository) : super(const AsyncValue.loading()) {
    loadUser();
  }

  Future<void> loadUser() async {
    try {
      final user = await _repository.getCurrentUser();
      state = AsyncValue.data(user);
    } catch (e, st) {
      state = AsyncValue.error(e, st);
    }
  }

  Future<void> saveUser(UserModel user) async {
    await _repository.saveUser(user);
    state = AsyncValue.data(user);
  }

  Future<void> updateUser(UserModel user) async {
    await _repository.updateUser(user);
    state = AsyncValue.data(user);
  }

  Future<bool> hasUser() async {
    return _repository.hasUser();
  }
}
