import 'package:flutter_animate/flutter_animate.dart';
import 'package:jarvis/core/theme/app_spacing.dart';

class JarvisCard extends StatelessWidget {
  final Widget child;
  final double padding;
  final VoidCallback? onTap;
  final Gradient? gradient;
  final Color? color;
  final bool animate;

  const JarvisCard({
    super.key,
    required this.child,
    this.padding = 20.0,
    this.onTap,
    this.gradient,
    this.color,
    this.animate = true,
  });

  @override
  Widget build(BuildContext context) {
    Widget card = Container(
      decoration: BoxDecoration(
        color: color ?? (gradient == null ? Colors.white : null),
        gradient: gradient,
        borderRadius: AppSpacing.radiusCard,
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.06),
            blurRadius: 16,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: Material(
        color: Colors.transparent,
        borderRadius: AppSpacing.radiusCard,
        child: InkWell(
          borderRadius: AppSpacing.radiusCard,
          onTap: onTap,
          child: Padding(
            padding: EdgeInsets.all(padding),
            child: child,
          ),
        ),
      ),
    );

    if (animate) {
      return card
          .animate()
          .fade(duration: 300.ms, curve: Curves.easeOutCubic)
          .scaleXY(begin: 0.96, end: 1.0, duration: 300.ms, curve: Curves.easeOutCubic);
    }

    return card;
  }
}
